   "ev-4081415f77fb"
  ]
 },
 "contributing_factors": [
  {
   "statement": "Orders has no fallback for inventory reservation failures. Every inventory 500 becomes an orders 502 and then a gateway 502: orders and inventory have identical error ratios (avg 21.2%, max 56.5%).",
